/*
 * Implementation of method get_info for interface afw_value.
 */
void
impl_afw_value_get_info(
    const afw_value_t *instance,
    afw_value_info_t *info,
    const afw_pool_t *p,
    afw_xctx_t *xctx)
{
    afw_memory_clear(info);
    info->value_inf_id = &instance->inf->rti.implementation_id;
    info->evaluated_data_type = afw_data_type_relaxed_json;
    info->optimized_value = instance;
}


/* Get next value from array of relaxed_json. */
AFW_DEFINE(const afw_utf8_t *)
afw_array_of_relaxed_json_get_next_source(
    const afw_array_t *instance,
    const afw_iterator_old_t * *iterator,
    const afw_utf8_z_t *source_z,
    afw_xctx_t *xctx)
{
    const void *internal;
    const afw_data_type_t *data_type;

    afw_array_get_next_internal(instance, iterator, &data_type, &internal, xctx);
    if (!internal) {
        return NULL;
    }
    if (data_type != afw_data_type_relaxed_json) {
        const afw_utf8_t *data_type_id;

        data_type_id = &data_type->data_type_id;
        afw_error_set_fz(afw_error_code_general, source_z, xctx,
            "Typesafe error: expecting 'relaxed_json' but "
            "encountered " AFW_UTF8_FMT_Q,
            AFW_UTF8_FMT_OPTIONAL_UNDEFINED_ARG(data_type_id));
        longjmp(((xctx)->current_try->throw_jmp_buf), afw_error_code_general);
    }
    return (const afw_utf8_t *)internal;
}

/* Add value from array of relaxed_json */
AFW_DEFINE(void)
afw_array_of_relaxed_json_add(
    const afw_array_t *instance,
    const afw_utf8_t *value,
    afw_xctx_t *xctx)
{
    const afw_array_setter_t *setter;

    setter = afw_array_get_setter(instance, xctx);
    if (!setter) {
        AFW_LIST_ERROR_OBJECT_IMMUTABLE;
    }

    afw_array_setter_push_internal(setter, 
        afw_data_type_relaxed_json,
        (const void *)value, xctx);
}

/* Remove value from array of relaxed_json */
AFW_DEFINE(void)
afw_array_of_relaxed_json_remove(
    const afw_array_t *instance,
    const afw_utf8_t *value,
    afw_xctx_t *xctx)
{
    const afw_array_setter_t *setter;

    setter = afw_array_get_setter(instance, xctx);
    if (!setter) {
        AFW_LIST_ERROR_OBJECT_IMMUTABLE;
    }

    afw_array_setter_remove_internal(setter, 
        afw_data_type_relaxed_json,
        (const void *)value, xctx);
}
